import json
import uuid

def generate_high_questions():
    questions = []
    def add_q(topic, q, opts, ans, exp):
        questions.append({
            "id": f"py-high-{uuid.uuid4().hex[:8]}",
            "language": "Python",
            "topic": topic,
            "difficulty": "High",
            "question": q,
            "options": opts,
            "correctAnswer": ans,
            "explanation": exp
        })

    # 1. Intro to Python
    add_q("Intro to Python", "What is the primary difference between CPython and PyPy?", ["CPython is compiled, PyPy is interpreted", "PyPy uses a Just-In-Time (JIT) compiler for performance, CPython does not", "CPython is written in C++, PyPy in Python", "There is no difference"], 1, "PyPy implements a JIT compiler that often executes Python code much faster than CPython's standard bytecode interpreter.")
    add_q("Intro to Python", "Which of the following describes 'duck typing' in Python?", ["Strong typing where types must match exactly", "If it walks like a duck and quacks like a duck, it must be a duck; type checking is bypassed in favor of method presence", "A feature that prevents TypeErrors", "Typing variables with the `duck` keyword"], 1, "Duck typing focuses on the object's capabilities (methods/properties) rather than its actual class type.")
    add_q("Intro to Python", "How does Python's garbage collector primarily handle cyclic references?", ["It ignores them, causing memory leaks", "Using reference counting only", "By utilizing a generational cyclic garbage collector that periodically runs", "By crashing the program"], 2, "While reference counting handles immediate cleanup, a generational garbage collector runs periodically to detect and clean up cyclic references.")
    add_q("Intro to Python", "What is an abstract syntax tree (AST) in the context of Python execution?", ["A graphical representation of code for IDEs", "The final machine code executed by the CPU", "A tree representation of the syntactic structure of the source code before compiling to bytecode", "A data structure for binary search"], 2, "Python parses source code into an AST before compiling it into the bytecode executed by the PVM.")
    add_q("Intro to Python", "What does the `dis` module do?", ["Disables garbage collection", "Disassembles Python bytecode into a human-readable format", "Disconnects the network socket", "Distributes Python packages"], 1, "The `dis` module allows you to inspect the bytecode instructions generated by the CPython compiler.")
    add_q("Intro to Python", "Which PEP introduced type hinting to Python?", ["PEP 8", "PEP 20", "PEP 484", "PEP 310"], 2, "PEP 484 introduced type hints (e.g., def func(a: int) -> str) to Python 3.5.")
    add_q("Intro to Python", "What does 'monkey patching' refer to in Python?", ["Fixing bugs in production", "Dynamically modifying or extending a class or module at runtime", "Using the `patch` decorator", "Writing code without tests"], 1, "Monkey patching is the practice of modifying code (like replacing a method of a class) dynamically during runtime.")
    add_q("Intro to Python", "In Python 3, how are integers implemented under the hood to prevent overflow?", ["They are limited to 64 bits", "They automatically convert to floats", "They are arbitrary-precision, allocating more memory as the number grows", "They overflow wrapping back to negative numbers"], 2, "Python 3 integers are unbounded; they transition to arbitrary-precision arithmetic automatically.")
    add_q("Intro to Python", "What is the purpose of `__slots__` in a class?", ["To define the methods a class can use", "To prevent the creation of `__dict__` and save memory for instances", "To schedule tasks in async Python", "To allow multiple inheritance"], 1, "`__slots__` restricts the valid attributes of a class to exactly those defined, saving the memory overhead of a per-instance dictionary.")
    add_q("Intro to Python", "Which of these is NOT a built-in namespace in Python?", ["Local", "Global", "Enclosing", "Lexical"], 3, "Python's namespace resolution rule is LEGB: Local, Enclosing, Global, Built-in. Lexical is a general scoping term, not a specific Python namespace.")

    # 2. Variables & Data Types
    add_q("Variables & Data Types", "What is the output of: `x = 256; y = 256; print(x is y)` vs `a = 257; b = 257; print(a is b)` in an interactive REPL?", ["True, True", "False, False", "True, False", "False, True"], 2, "CPython caches small integers from -5 to 256. Variables assigned to 256 point to the same cached object, while 257 creates new objects in the REPL.")
    add_q("Variables & Data Types", "What happens when you create a shallow copy of a list containing mutable objects?", ["The mutable objects are deeply copied", "Modifying the nested mutable objects in the copy affects the original", "It throws a TypeError", "The list becomes immutable"], 1, "A shallow copy duplicates the outer list but keeps references to the same inner mutable objects (like nested lists).")
    add_q("Variables & Data Types", "What is the result of `type(type(int))`?", ["<class 'int'>", "<class 'type'>", "<class 'object'>", "Error"], 1, "The type of 'int' is 'type', and the type of 'type' itself is 'type'.")
    add_q("Variables & Data Types", "Why might `0.1 + 0.2 == 0.3` evaluate to False?", ["Floating point arithmetic uses IEEE 754 representation, causing small precision errors", "Python cannot add floats correctly", "0.3 is considered a double, while 0.1 is a float", "Type mismatch error"], 0, "Binary floating-point cannot perfectly represent 0.1 and 0.2, leading to 0.30000000000000004.")
    add_q("Variables & Data Types", "What does it mean that Python passes arguments by 'assignment' (or 'object reference')?", ["Values are deeply copied to the function", "Pointers to memory addresses are copied, allowing mutable objects to be changed in place", "Variables cannot be changed in a function", "It uses pass-by-reference like C++"], 1, "Python passes the reference to the object. If the object is mutable, changes affect the caller's variable.")
    add_q("Variables & Data Types", "What is the output of `hash(float('inf'))`?", ["Error, unhashable type", "314159", "0", "An integer representing infinity's hash"], 3, "Infinity is a valid float, and floats are immutable and hashable, so it returns a specific integer hash (314159 in CPython).")
    add_q("Variables & Data Types", "How does Python differentiate a tuple with one element from a mathematical parenthesis?", ["(5) is a tuple, (5,) is math", "(5,) is a tuple, (5) is an integer", "There is no difference", "Using the `tuple` keyword only"], 1, "The trailing comma is mandatory for a single-element tuple: (5,).")
    add_q("Variables & Data Types", "What is the `__dict__` attribute of an object?", ["A dictionary containing the object's methods", "A dictionary containing the object's writable attributes/state", "A built-in dictionary for string translation", "The class definition"], 1, "Most objects in Python store their instance attributes in the `__dict__` dictionary.")
    add_q("Variables & Data Types", "What happens if a class defines both `__str__` and `__repr__` and you call `print(obj)`?", ["`__repr__` is called", "`__str__` is called", "An error is raised", "Both are called"], 1, "print() uses `str()`, which falls back to `__repr__` only if `__str__` is not defined. Since both exist, `__str__` is preferred.")
    add_q("Variables & Data Types", "Which module provides exact decimal arithmetic suitable for financial applications?", ["math", "cmath", "decimal", "fractions"], 2, "The `decimal` module provides a Decimal datatype for fast correctly-rounded decimal floating point arithmetic.")

    # 3. Sequence of Instructions
    add_q("Sequence of Instructions", "In Python, can a function definition inside an `if` block override a previous function definition?", ["No, function names are constants", "Yes, function definition is an executable statement bound at runtime", "Only if it uses the `global` keyword", "It causes a SyntaxError"], 1, "Because Python executes line by line, `def` is an executable statement. Redefining a function overwrites the name reference.")
    add_q("Sequence of Instructions", "What is the order of execution in a `try-except-else-finally` block if no exception occurs?", ["try -> finally", "try -> else -> finally", "try -> except -> finally", "try -> else"], 1, "The `else` block executes because no exception was raised, followed by the `finally` block.")
    add_q("Sequence of Instructions", "What is the output of:\ndef f():\n  try: return 1\n  finally: return 2\nprint(f())", ["1", "2", "Error", "None"], 1, "The `finally` block executes immediately before the `try` block returns, and its `return` overrides the `try`'s return.")
    add_q("Sequence of Instructions", "What is the 'walrus operator' (`:=`) used for?", ["Defining constants", "Assignment expressions that return the value being assigned", "Type hinting", "Creating bitwise masks"], 1, "The walrus operator allows you to assign a value to a variable as part of an expression, like inside an `if` or `while` condition.")
    add_q("Sequence of Instructions", "How are decorators executed in relation to the function they wrap?", ["They execute when the function is called", "They execute immediately when the function is defined", "They execute at compile time", "They execute when the script exits"], 1, "Decorators are evaluated and executed at the time the function is defined, wrapping the original function.")
    add_q("Sequence of Instructions", "If `__init__.py` executes initialization code, when does it run?", ["Every time a module in the package is imported", "Only the first time the package or a module in the package is imported", "When the package is uninstalled", "Never"], 1, "Python caches imports in `sys.modules`. `__init__.py` runs only once per session upon initial import.")
    add_q("Sequence of Instructions", "What is 'lazy evaluation' in the context of Python generators?", ["The code executes slowly", "Values are computed only when they are needed, one at a time", "The compiler delays syntax checking", "Variables are initialized to None"], 1, "Generators yield values on demand (lazily), which saves memory and avoids computing the entire sequence upfront.")
    add_q("Sequence of Instructions", "What happens if a module attempts to import itself circularly?", ["It instantly crashes with RecursionError", "It successfully imports an empty reference if the required names are not yet defined", "The interpreter completely bypasses it", "It raises ImportError immediately"], 1, "Circular imports can succeed if the importing module doesn't immediately use uninitialized attributes from the partially loaded module.")
    add_q("Sequence of Instructions", "What is the execution context provided by the `with` statement?", ["It ensures a loop executes fully", "It automatically calls `__enter__()` before the block and `__exit__()` after, ensuring cleanup", "It suppresses all errors", "It creates a new thread"], 1, "The `with` statement simplifies exception handling by encapsulating common preparation and cleanup tasks (Context Managers).")
    add_q("Sequence of Instructions", "If a variable is used in an inner function before being declared as `nonlocal`, what happens?", ["UnboundLocalError", "It references the global variable", "It returns None", "SyntaxError"], 0, "Python assumes any variable assigned to in a scope is local. Using it before assignment in that scope raises an UnboundLocalError.")

    # 4. Input & Output Basics
    add_q("Input & Output Basics", "How do you parse a JSON string from an API response into a Python dictionary?", ["json.parse(response)", "json.load(response)", "json.loads(response)", "dict(response)"], 2, "`loads()` (load string) is used to parse a JSON formatted string into a dictionary.")
    add_q("Input & Output Basics", "What is the difference between `json.dump()` and `json.dumps()`?", ["dump() returns a string, dumps() writes to a file", "dump() writes to a file object, dumps() returns a string", "There is no difference", "dumps() is for secure serialization"], 1, "The 's' in `dumps` stands for string. `dump` takes a file pointer as an argument.")
    add_q("Input & Output Basics", "How do you serialize a custom Python object (like a class instance) using `json`?", ["It happens automatically", "By overriding `__str__`", "By providing a custom encoding function to the `default` parameter of `json.dumps`", "Using `pickle` only"], 2, "The `json` module cannot serialize custom objects natively; you must provide a `default` function to convert them to dictionaries first.")
    add_q("Input & Output Basics", "When writing binary data (like an image) to a file, what mode should be used?", ["'w'", "'wb'", "'w+'", "'b'"], 1, "The 'wb' mode opens a file for writing in binary format.")
    add_q("Input & Output Basics", "What does `sys.stdout.flush()` do?", ["Clears the console screen", "Forces the output buffer to be written to the terminal immediately", "Deletes the output stream", "Throws an error"], 1, "Output is often buffered. `flush()` forces Python to push the buffered data out immediately.")
    add_q("Input & Output Basics", "How do you read a large file in a memory-efficient way?", ["file.read()", "file.readlines()", "for line in file:", "file.read_all()"], 2, "Iterating directly over the file object reads it line by line, preventing the entire file from loading into memory.")
    add_q("Input & Output Basics", "What is the purpose of the `pickle` module?", ["Formatting text files", "Compressing files", "Serializing and deserializing Python object structures (binary format)", "Parsing XML"], 2, "`pickle` converts complex Python objects into byte streams and vice versa, though it is insecure for untrusted data.")
    add_q("Input & Output Basics", "What exception is raised if you try to open a non-existent file in 'r' mode?", ["IOError", "FileNotFoundError", "FileError", "MissingFileError"], 1, "Python 3 raises a FileNotFoundError, which is a subclass of OSError.")
    add_q("Input & Output Basics", "What does the `csv.DictReader` class do?", ["Writes dictionaries to a CSV file", "Reads CSV rows into dictionaries using the first row as keys", "Converts a dictionary to a string", "Validates CSV syntax"], 1, "It maps the information in each row to a dict whose keys are given by the optional fieldnames parameter or the first row.")
    add_q("Input & Output Basics", "How do you correctly use the `logging` module to output to both a file and the console?", ["Use print and write simultaneously", "Configure multiple handlers (FileHandler and StreamHandler) in the logging config", "Call logging twice", "It is not possible"], 1, "The `logging` module is highly configurable and supports attaching multiple handlers to a single logger.")

    # 5. Type Conversions
    add_q("Type Conversions", "What is the result of `list(zip([1, 2], ['a', 'b']))`?", ["[(1, 'a'), (2, 'b')]", "[1, 'a', 2, 'b']", "((1, 'a'), (2, 'b'))", "Error"], 0, "zip() pairs elements into tuples, and list() converts the zip iterator into a list of tuples.")
    add_q("Type Conversions", "How do you create a dictionary from a list of tuples like `[('a', 1), ('b', 2)]`?", ["dict([('a', 1), ('b', 2)])", "to_dict([('a', 1), ('b', 2)])", "{[('a', 1), ('b', 2)]}", "dictionary([('a', 1), ('b', 2)])"], 0, "The dict() constructor accepts an iterable of key-value pairs.")
    add_q("Type Conversions", "What happens when you cast a dictionary to a list `list({'a': 1, 'b': 2})`?", ["Returns `[{'a': 1}, {'b': 2}]`", "Returns `['a', 'b']` (only the keys)", "Returns `[1, 2]` (only the values)", "Raises a TypeError"], 1, "Iterating over a dictionary yields its keys, so list() extracts only the keys.")
    add_q("Type Conversions", "How do you convert a string like '2023-10-05' into a `datetime` object?", ["datetime.datetime('2023-10-05')", "datetime.strptime('2023-10-05', '%Y-%m-%d')", "datetime.parse('2023-10-05')", "cast('2023-10-05', datetime)"], 1, "The strptime() method parses a string representing a time according to a format.")
    add_q("Type Conversions", "What is the output of `bool(float('nan'))`?", ["True", "False", "Error", "None"], 0, "NaN (Not a Number) is a valid non-zero float, so it evaluates to True in a boolean context.")
    add_q("Type Conversions", "How do you unpack a dictionary `d1 = {'a': 1}` into another dictionary?", ["d2 = {d1, 'b': 2}", "d2 = {**d1, 'b': 2}", "d2 = {*d1, 'b': 2}", "d2 = {d1: 'b'}"], 1, "The double asterisk (**) operator unpacks the key-value pairs of a dictionary.")
    add_q("Type Conversions", "What does `bytes('hello', 'utf-8')` do?", ["Converts string to a tuple", "Converts string to an immutable sequence of bytes", "Raises a SyntaxError", "Converts string to binary base 2"], 1, "The bytes() function encodes the string into a bytes object using the specified encoding.")
    add_q("Type Conversions", "What is the result of `int('10a', 16)`?", ["TypeError", "ValueError", "266", "10"], 2, "In hexadecimal (base 16), 'a' represents 10. So '10a' is 1*256 + 0*16 + 10 = 266.")
    add_q("Type Conversions", "How do you convert a list of integers `[1, 2, 3]` into a single integer `123`?", ["int(list)", "int(''.join(map(str, [1, 2, 3])))", "sum([1, 2, 3])", "merge([1, 2, 3])"], 1, "You must map the integers to strings, join them into a single string, and then cast to int.")
    add_q("Type Conversions", "What is the output of `set([1, 2, 2, 3])`?", ["{1, 2, 2, 3}", "{1, 2, 3}", "Error", "[1, 2, 3]"], 1, "Converting a list to a set automatically removes duplicate values, resulting in {1, 2, 3}.")

    # 6. Relational Operations
    add_q("Relational Operations", "In Python, can you override the behavior of relational operators like `<` and `==` for custom classes?", ["No", "Yes, by overriding `__lt__` and `__eq__` methods", "Only for `==` using `__equals__`", "Only if the class inherits from int"], 1, "Python's data model allows operator overloading via special (dunder) methods.")
    add_q("Relational Operations", "What is the output of `float('nan') == float('nan')`?", ["True", "False", "Error", "None"], 1, "By the IEEE 754 standard, NaN is never equal to anything, including itself.")
    add_q("Relational Operations", "How does `functools.total_ordering` simplify relational operations for custom classes?", ["It automatically defines all methods without you doing anything", "If you define `__eq__` and one other ordering method (e.g., `__lt__`), it auto-generates the rest", "It sorts lists automatically", "It prevents objects from being compared"], 1, "It is a class decorator that fills in missing ordering methods based on the ones you provide.")
    add_q("Relational Operations", "What happens when you compare a list and a tuple, e.g., `[1, 2] == (1, 2)`?", ["True", "False", "TypeError", "SyntaxError"], 1, "They are different types (list vs tuple), so they evaluate to False, even if their contents look identical.")
    add_q("Relational Operations", "What is the output of `1 == True` and `1 is True`?", ["True, True", "False, False", "True, False", "False, True"], 2, "Values are equal (True is 1), but they are different objects (int vs bool), so 'is' returns False.")
    add_q("Relational Operations", "When sorting a list of dictionaries, how can you specify which key to compare?", ["list.sort(by='key')", "list.sort(key=lambda x: x['key'])", "list.sort_dict('key')", "You cannot sort dictionaries"], 1, "The `key` parameter of the sort method takes a function that extracts a comparison key from each element.")
    add_q("Relational Operations", "What happens during dictionary comparison `d1 == d2`?", ["Only the keys are compared", "Only the values are compared", "It checks if they point to the same memory", "It checks if both have exactly the same key-value pairs (order doesn't matter in Python 3)"], 3, "Dictionaries are equal if they have the exact same keys and corresponding values, regardless of insertion order.")
    add_q("Relational Operations", "What does `isinstance(type, object)` and `isinstance(object, type)` return?", ["True, True", "True, False", "False, True", "False, False"], 0, "Everything inherits from object (including type), and object is an instance of type. Both are True.")
    add_q("Relational Operations", "What is the output of `False == False == False`?", ["True", "False", "SyntaxError", "TypeError"], 0, "Chained comparison evaluates as `(False == False) and (False == False)`, which is `True and True`, resulting in True.")
    add_q("Relational Operations", "If `__eq__` is overridden in a class, is `__hash__` affected?", ["No, they are independent", "Yes, `__hash__` becomes None implicitly, making the object unhashable", "Yes, `__hash__` automatically updates to match", "It causes a TypeError"], 1, "If a class overrides `__eq__` without defining `__hash__`, Python marks it as unhashable (since mutable objects shouldn't be in sets/dicts).")

    # 7. Logical Operators
    add_q("Logical Operators", "What is the result of `all([])` and `any([])`?", ["True, True", "False, False", "True, False", "False, True"], 2, "all() on an empty iterable returns True (vacuous truth). any() on an empty iterable returns False (no elements are truthy).")
    add_q("Logical Operators", "What is the output of `~True` (bitwise NOT)?", ["False", "-1", "-2", "0"], 2, "True is integer 1. Bitwise NOT inverts bits: ~x is equivalent to -x - 1. So, ~1 is -2.")
    add_q("Logical Operators", "What is the difference between `&` and `and` when dealing with sets?", ["They are the same", "`&` performs intersection, `and` performs logical evaluation", "`and` performs intersection", "`&` performs union"], 1, "The `&` operator is overloaded in sets to mean intersection, while `and` is strictly for boolean logic.")
    add_q("Logical Operators", "What happens when using `and` with pandas Series or numpy Arrays?", ["It works normally", "It returns True", "Raises ValueError: The truth value of a Series/Array is ambiguous", "It acts like element-wise `&`"], 2, "You must use the bitwise operators `&` and `|` for element-wise logical operations on pandas/numpy arrays.")
    add_q("Logical Operators", "What is the output of `1 and 2 or 3`?", ["1", "2", "3", "Error"], 1, "'and' has higher precedence. (1 and 2) yields 2. (2 or 3) yields 2.")
    add_q("Logical Operators", "What is the output of `'a' or 'b' and 'c'`?", ["'a'", "'b'", "'c'", "True"], 0, "'and' has higher precedence. 'b' and 'c' yields 'c'. 'a' or 'c' yields 'a'.")
    add_q("Logical Operators", "If you define a custom class, how do you make its instances evaluate to False?", ["Override `__false__()`", "Override `__bool__()` to return False or `__len__()` to return 0", "You cannot", "Set `self.value = False`"], 1, "Python checks `__bool__()`. If not defined, it checks `__len__()`. If neither, the object is True.")
    add_q("Logical Operators", "Can logical short-circuiting be used to prevent attribute errors, like `if obj and obj.val:`?", ["Yes", "No", "Only if obj is a dictionary", "Only in Python 2"], 0, "Yes, if `obj` is None (falsy), the `and` short-circuits, preventing `obj.val` from throwing an AttributeError.")
    add_q("Logical Operators", "What does `x = y = z = []` followed by `x.append(1)` do?", ["Only x becomes [1]", "x, y, and z all become [1]", "Throws an error", "Only x and y become [1]"], 1, "Chained assignment makes all variables reference the exact same mutable list object.")
    add_q("Logical Operators", "What is the boolean evaluation of a generator expression `(x for x in [])`?", ["False", "True", "None", "Error"], 1, "A generator object itself is truthy, regardless of whether it will yield elements or is exhausted.")

    # 8. Conditional Statements
    add_q("Conditional Statements", "What happens when you use a tuple containing elements as a condition, e.g., `if (False,):`?", ["It evaluates to False", "It evaluates to True", "It raises a TypeError", "It evaluates to None"], 1, "A tuple with elements (even False or None) is not empty, so it is considered truthy.")
    add_q("Conditional Statements", "How does structural pattern matching (`match` statement) handle variable binding in Python 3.10+?", ["It cannot bind variables", "It uses the `bind` keyword", "It binds matching components to new variables directly within the `case` pattern", "It overwrites global variables only"], 2, "Patterns like `case [x, y]:` bind `x` and `y` to the list's elements automatically.")
    add_q("Conditional Statements", "What is the output of `x = [1, 2]; print('Yes') if x.pop() else print('No')`?", ["Yes", "No", "SyntaxError", "Prints nothing"], 0, "`x.pop()` returns 2 (truthy), so the ternary operator evaluates the True expression and prints 'Yes'.")
    add_q("Conditional Statements", "What is a 'Dispatch Table' (using a dictionary) an alternative to?", ["A while loop", "A long if-elif-else chain", "A nested list", "A try-except block"], 1, "Instead of many `elif`s, you can map keys to functions in a dictionary and call them dynamically.")
    add_q("Conditional Statements", "Can the `match` statement check for type safety, like `case int(x):`?", ["Yes, it supports type matching natively", "No, it only checks values", "Only using the `isinstance` keyword", "Yes, but only for strings"], 0, "The match statement can match patterns based on class types, e.g., `case str(x):`.")
    add_q("Conditional Statements", "What happens in a ternary operator if you omit the `else` clause? e.g. `x = 5 if True`", ["x becomes None", "x becomes 5", "SyntaxError", "x becomes False"], 2, "The Python ternary operator requires both the `if` and `else` clauses.")
    add_q("Conditional Statements", "What does `case _:` mean in a Python 3.10 `match` block?", ["Match a private variable", "Syntax error", "The default wildcard case (matches anything not previously matched)", "Match an underscore string"], 2, "The underscore `_` acts as a wildcard catch-all, similar to `default` in switch statements.")
    add_q("Conditional Statements", "If `A = True` and `B = False`, what is the output of `print(1 if A else 2 if B else 3)`?", ["1", "2", "3", "Error"], 0, "Nested ternary operators evaluate left-to-right. Since A is True, it immediately returns 1.")
    add_q("Conditional Statements", "Can you use assignment inside an `if` condition using Python 3.8+?", ["No", "Yes, using `=`", "Yes, using the walrus operator `:=`", "Yes, using `==`"], 2, "The walrus operator `:=` allows assignment within an expression, like `if (n := len(a)) > 10:`.")
    add_q("Conditional Statements", "Is it valid to have an `if` block containing only a docstring (triple quotes)?", ["Yes, it acts like a pass statement", "No, it raises an IndentationError", "No, it raises a SyntaxError", "Only in functions"], 0, "A docstring or any string literal is a valid statement. It does nothing and acts like `pass`.")

    # 9. Nested Conditional Statements
    add_q("Nested Conditional Statements", "What is the Cyclomatic Complexity of a function?", ["The speed of the function", "A software metric measuring the number of linearly independent paths through code (affected by nested ifs)", "The amount of memory it uses", "The number of loops"], 1, "Deeply nested conditionals increase Cyclomatic Complexity, making code harder to test and maintain.")
    add_q("Nested Conditional Statements", "How can De Morgan's Laws help simplify nested conditionals?", ["By proving the code is bug-free", "By rewriting complex negated AND/OR logic into simpler, flatter expressions", "By replacing ifs with loops", "By removing variables"], 1, "De Morgan's laws (e.g., `not (A and B)` is `not A or not B`) help flatten and clarify nested logic.")
    add_q("Nested Conditional Statements", "When refactoring nested `if` statements in a function, what is the strategy of returning as soon as a condition fails called?", ["Bouncer pattern / Guard clauses", "Arrow anti-pattern", "Looping", "Recursion"], 0, "Guard clauses exit early, keeping the 'main' logic un-nested at the bottom of the function.")
    add_q("Nested Conditional Statements", "What is the output of:\nif 'a' in 'abc':\n  if 1 == 2:\n    print(1)\nelse:\n  print(2)", ["1", "2", "Nothing", "Error"], 2, "The outer `if` is True, so it enters the block. The inner `if` is False. There is no inner `else`, and it skips the outer `else`. Nothing prints.")
    add_q("Nested Conditional Statements", "Can exception handling (`try-except`) be used as an alternative to deeply nested state-checking `if`s?", ["No, it is much slower", "No, it is poor practice", "Yes, (EAFP - Easier to Ask for Forgiveness than Permission) is a core Python idiom", "Only in Python 2"], 2, "Python encourages EAFP over LBYL (Look Before You Leap), often replacing nested `if` checks with a clean `try-except`.")
    add_q("Nested Conditional Statements", "How does a nested `match` statement handle complex data extraction?", ["It cannot handle it", "It allows deep structural pattern matching to extract deeply nested values in one line", "It requires loops", "It uses regex"], 1, "Pattern matching can deeply inspect dictionaries, lists, and objects to extract nested data cleanly.")
    add_q("Nested Conditional Statements", "If you need to execute the exact same block of code from multiple different nested `if` branches, what is the best practice?", ["Copy and paste the code", "Use a `goto`", "Extract the block into a helper function and call it", "Use a global variable"], 2, "Extracting shared logic into functions follows the DRY (Don't Repeat Yourself) principle.")
    add_q("Nested Conditional Statements", "What is the 'Arrow Anti-Pattern'?", ["Code that relies too much on lambda functions", "Code that is indented so many times it looks like an arrowhead pointing right", "A specific sorting algorithm", "Using too many > or < operators"], 1, "The Arrow Anti-Pattern refers to heavily nested conditional logic that hurts readability.")
    add_q("Nested Conditional Statements", "What is the output of:\nx = 0\nif x:\n  if x == 0:\n    print('A')\n  elif x < 1:\n    print('B')", ["A", "B", "Nothing", "Error"], 2, "`x = 0` is falsy. The outer `if x:` fails, so the entire nested block is skipped. Nothing prints.")
    add_q("Nested Conditional Statements", "In a scenario with 4 independent boolean variables leading to 16 outcomes, what is the cleanest alternative to 16 nested `if/else` statements?", ["A decision matrix / dict mapping tuples of booleans to actions", "A while loop", "A class for each variable", "You must use 16 ifs"], 0, "Mapping `(A, B, C, D)` to specific functions using a dictionary is far cleaner than massive nesting.")

    # 10. Loops (while loop, for loop)
    add_q("Loops", "How does a `for` loop actually work under the hood in Python?", ["It uses a while loop with an index", "It calls `iter()` on the object and repeatedly calls `next()` until StopIteration is raised", "It recursively calls the object", "It converts the object to a list first"], 1, "The for loop is essentially syntactic sugar for handling the Iterator Protocol manually.")
    add_q("Loops", "What is the output of `for x in iter(int, 1): pass`?", ["SyntaxError", "An infinite loop", "It does nothing", "Raises TypeError"], 1, "The two-argument form of `iter(callable, sentinel)` calls the callable until it returns the sentinel. `int()` always returns 0, so it never hits 1, creating an infinite loop.")
    add_q("Loops", "What does `itertools.cycle` do when used in a `for` loop?", ["Runs the loop once", "Iterates over an iterable, and when exhausted, starts over from the beginning indefinitely", "Reverses the iterable", "Sorts the iterable"], 1, "`cycle` creates an infinite iterator that loops over a sequence repeatedly.")
    add_q("Loops", "How do you modify the iteration step in a `for` loop when not using `range` (e.g., over a list)?", ["`for x in lst step 2:`", "`for x in lst[::2]:`", "`for x in lst(step=2):`", "`for x in step(lst, 2):`"], 1, "List slicing `lst[::2]` creates a new list with every second element for the loop to iterate over.")
    add_q("Loops", "What is a 'generator expression' and how does it differ from a list comprehension in a loop?", ["They are the same", "A generator uses `()` and yields items lazily; a comprehension uses `[]` and builds the whole list in memory", "A generator uses `{}`", "A generator cannot be looped over"], 1, "Generators are extremely memory efficient because they compute the next value only when requested.")
    add_q("Loops", "What happens if a dictionary size changes during a `for k in dict:` loop?", ["The loop continues normally", "RuntimeError: dictionary changed size during iteration", "The loop skips the new keys", "The loop restarts"], 1, "Python strictly prohibits modifying the size of a dictionary while actively iterating over it.")
    add_q("Loops", "What is the output of:\na = [1, 2]\nfor x in a:\n  a.append(x * 2)", ["Prints 1, 2", "SyntaxError", "An infinite loop causing MemoryError", "The loop runs twice"], 2, "Appending to a list while iterating over it pushes the end of the list further away, causing an infinite loop.")
    add_q("Loops", "How does the `else` clause in a `while` loop behave if the condition is False initially?", ["It raises an error", "It is skipped", "It executes immediately", "It waits for True"], 2, "If the loop never enters, it finishes without a `break`, so the `else` block executes immediately.")
    add_q("Loops", "What is the purpose of `itertools.islice` in a loop?", ["To slice a list without copying it in memory, working on any iterator", "To slice strings only", "To reverse an iterator", "To join iterators"], 0, "Unlike list slicing which copies data, `islice` lazily consumes the iterator, saving memory.")
    add_q("Loops", "Can a Python loop execute 0 times?", ["Yes, if the iterable is empty or condition is False", "No, loops must execute at least once", "Only `while` loops can", "Only `for` loops can"], 0, "If a `for` loop is given an empty list, or a `while` condition is immediately False, the body is never executed.")

    # 11. String Methods
    add_q("String Methods", "What is the time complexity of repeatedly concatenating strings in a loop using `s += new_str` in CPython?", ["O(1)", "O(N)", "O(N^2) historically, but optimized in CPython 3 to O(N)", "O(log N)"], 2, "While historically O(N^2) due to immutability, CPython has an in-place optimization that often makes it O(N). However, `join()` is still the recommended practice.")
    add_q("String Methods", "How do you translate characters in a string using a mapping table?", ["str.replace_all(map)", "str.translate(table)", "str.map(table)", "str.convert(table)"], 1, "The `translate(table)` method uses a translation table created by `str.maketrans()` to replace characters.")
    add_q("String Methods", "What does `str.casefold()` do?", ["Capitalizes the string", "Converts to title case", "Provides an aggressive, Unicode-aware lowercase conversion suitable for caseless matching", "Swaps case"], 2, "Unlike `lower()`, `casefold()` converts characters like the German 'ß' to 'ss', making it better for strict caseless comparisons.")
    add_q("String Methods", "What is the output of `'abc'.encode('utf-8')`?", ["'abc'", "b'abc'", "['a', 'b', 'c']", "Error"], 1, "The `encode()` method converts a string (Unicode) into a bytes object.")
    add_q("String Methods", "Which method returns a copy of the string where all tab characters are replaced by one or more spaces?", ["str.expandtabs()", "str.removetabs()", "str.replace('\\t', ' ')", "str.spaces()"], 0, "The `expandtabs()` method replaces tab characters with spaces based on the tabsize parameter.")
    add_q("String Methods", "What does `'ab c'.split(maxsplit=1)` return?", ["['a', 'b', 'c']", "['ab', 'c']", "['a', 'b c']", "Error"], 2, "The `maxsplit` argument limits the number of splits. It splits at the first whitespace, resulting in ['a', 'b c'].")
    add_q("String Methods", "What does `str.isidentifier()` check?", ["If the string is a valid Python keyword", "If the string is a valid variable name (identifier)", "If the string contains only letters", "If the string has an ID"], 1, "It returns True if the string is a valid identifier according to the language definition (e.g., starts with a letter/underscore).")
    add_q("String Methods", "What happens when using `format_map()` instead of `format()`?", ["format_map() takes a single dictionary-like object directly without unpacking", "There is no difference", "format_map() is faster for lists", "format_map() modifies in place"], 0, "`format_map(mapping)` is useful because it doesn't require unpacking `**mapping`, allowing the use of custom dictionary subclasses (like defaultdict).")
    add_q("String Methods", "How do you right-justify a string in a field of a given width?", ["str.right()", "str.rjust(width)", "str.align('right')", "str.justify()"], 1, "The `rjust(width)` method pads the string on the left with spaces to right-align the text.")
    add_q("String Methods", "What does `'abcdef'.removeprefix('abc')` return (Python 3.9+)?", ["'def'", "'abcdef'", "'cdef'", "Error"], 0, "Introduced in Python 3.9, `removeprefix()` cleanly removes the specified prefix if it exists.")

    # 12. Nested Loops
    add_q("Nested Loops", "What is the behavior of the `itertools.product` function?", ["It multiplies all elements in a list", "It creates a Cartesian product of input iterables, equivalent to nested for-loops", "It sorts nested loops", "It yields nothing"], 1, "`product(A, B)` yields the same items as `((x,y) for x in A for y in B)`, avoiding deep visual nesting.")
    add_q("Nested Loops", "How do you flatten a 2D list `matrix` using a list comprehension?", ["`[val for val in matrix]`", "`[val for row in matrix for val in row]`", "`[row for val in matrix]`", "`matrix.flatten()`"], 1, "The loops in the comprehension are ordered the same way they would be written in standard nested loops: outer first, inner second.")
    add_q("Nested Loops", "When implementing a Matrix Multiplication algorithm, what is the standard loop nesting structure?", ["One loop", "Two nested loops", "Three nested loops (row, col, dot product)", "Recursion only"], 2, "Standard matrix multiplication (O(N^3)) requires three nested loops: iterate rows of A, cols of B, and an inner loop for the dot product.")
    add_q("Nested Loops", "What is the Space Complexity of a double nested loop that modifies a matrix in place?", ["O(1)", "O(N)", "O(N^2)", "O(N^3)"], 0, "Because the matrix is modified in-place and no new proportional memory is allocated, the auxiliary space complexity is O(1).")
    add_q("Nested Loops", "What happens if an exception is raised inside the innermost loop of a 3-level nested loop?", ["Only the innermost loop stops", "The exception propagates outward, terminating all loops unless caught by a try-except block", "The outer loops restart", "It acts like a continue statement"], 1, "Exceptions break the normal flow of control completely, bubbling up the call stack and terminating all enclosing loops.")
    add_q("Nested Loops", "In what scenario does reversing the order of nested loops (looping cols then rows instead of rows then cols) drastically affect performance?", ["Never", "When working with small arrays", "Due to CPU cache locality and memory access patterns (row-major order)", "Only in Python 2"], 2, "Accessing memory sequentially (row by row in C-like arrays/NumPy) is much faster due to CPU caching than jumping across columns.")
    add_q("Nested Loops", "What does the following generator expression do: `((i, j) for i in range(3) for j in range(i, 3))`?", ["Creates a full Cartesian product", "Generates combinations with replacement (upper triangle of a matrix)", "Generates a syntax error", "Loops infinitely"], 1, "Because the inner loop starts at `i`, it yields pairs like (0,0), (0,1), (0,2), (1,1)... avoiding duplicate unordered pairs.")
    add_q("Nested Loops", "Is it possible to yield from a nested loop recursively?", ["No, yield only works in flat loops", "Yes, using the `yield from` keyword", "Only using return", "Only in async loops"], 1, "`yield from` delegates part of its operations to another generator, which is highly useful for recursive nested generation (like traversing a tree).")
    add_q("Nested Loops", "What is the output of:\nfor i in []:\n  for j in [1, 2]:\n    print(j)\nelse:\n  print('Done')", ["1\n2\nDone", "Done", "Error", "Nothing"], 1, "The outer loop is empty, so it never executes the inner loop. It completes normally and hits the `else` block, printing 'Done'.")
    add_q("Nested Loops", "How do you elegantly iterate over a nested dictionary (e.g., JSON response)?", ["Using nested loops blindly", "Using recursive functions", "Using `itertools.chain`", "Python does not allow it"], 1, "Because the depth of JSON is often unknown, a recursive function containing a loop is the standard way to traverse nested dictionaries.")

    # 13. Loop Control Statements
    add_q("Loop Control Statements", "Can you use the `break` statement inside a list comprehension?", ["Yes, it breaks the comprehension", "No, `break` is not syntactically valid inside comprehensions", "Yes, but only at the end", "Only if it is inside an `if`"], 1, "List comprehensions are expressions, not statements. `break` and `continue` cannot be used inside them.")
    add_q("Loop Control Statements", "How can you simulate a `break` in a list comprehension?", ["Use `itertools.takewhile` or similar generator patterns", "Use the `stop` keyword", "Use an `if` clause (it filters, but doesn't break early)", "You cannot"], 0, "`takewhile(condition, iterable)` acts like a `break` by stopping the generator the moment the condition fails.")
    add_q("Loop Control Statements", "What happens if you raise a `StopIteration` exception manually inside a `for` loop?", ["The loop catches it and terminates normally", "The program crashes with a Traceback", "The loop restarts", "It acts like `continue`"], 1, "In modern Python (PEP 479), raising `StopIteration` inside a generator or loop body manually will bubble up as a RuntimeError or crash, it is not caught automatically by the enclosing `for`.")
    add_q("Loop Control Statements", "If a loop is wrapped in a `try...finally` block, and a `break` is encountered, does the `finally` block execute?", ["No, `break` bypasses `finally`", "Yes, `finally` executes before the loop is exited", "Yes, but only if an error occurred", "It throws a SyntaxError"], 1, "The `finally` block is guaranteed to execute, even if control flow leaves the `try` block via `break`, `continue`, or `return`.")
    add_q("Loop Control Statements", "What is the output of:\ndef f():\n  for i in range(3):\n    try: continue\n    finally: print(i)\nf()", ["0\n1\n2", "Error", "Nothing", "2"], 0, "Even though `continue` skips the rest of the loop, the `finally` block must execute before the next iteration begins.")
    add_q("Loop Control Statements", "What is the best way to break out of multiple nested loops dynamically without a flag?", ["Use `break all`", "Use a custom Exception and wrap the loops in a try-except block", "Use `sys.exit()`", "Use `pass`"], 1, "Raising a specific exception and catching it outside the outer loop is a clean, Pythonic way to break deeply nested loops.")
    add_q("Loop Control Statements", "How does a `break` statement affect the `else` clause of a `while` loop?", ["It triggers the `else` clause", "It skips the `else` clause", "It causes a syntax error", "It loops the `else` clause"], 1, "The `else` clause only executes if the loop terminates normally (i.e., the condition becomes false). `break` bypasses it.")
    add_q("Loop Control Statements", "Is `continue` allowed inside a `finally` block?", ["Yes, always", "No, it is a SyntaxError in Python 3.8+", "Yes, but only in Python 2", "Only if it is nested inside an `if`"], 1, "Historically it was restricted, and in modern Python, using `continue` directly inside a `finally` block that is not inside another loop causes issues/errors due to complex control flow.")
    add_q("Loop Control Statements", "What is the output of:\nwhile False:\n  break\nelse:\n  print('A')", ["A", "Nothing", "Error", "An infinite loop"], 0, "The `while` condition is False, so the loop body (and the `break`) is never reached. The loop completes normally, triggering `else`.")
    add_q("Loop Control Statements", "What is the difference between `sys.exit()`, `quit()`, and `break` in a script running a loop?", ["They are all identical", "`break` exits the loop; `sys.exit()` and `quit()` terminate the entire Python process", "`quit()` exits the loop", "`sys.exit()` pauses the loop"], 1, "`break` is local to the loop structure, while the others raise SystemExit to kill the whole program.")

    # 14. Comparing Strings & Naming Variables
    add_q("Comparing Strings & Naming Variables", "Why is comparing large strings with `==` in Python generally fast?", ["Strings are sorted", "Python first checks if the string identities or lengths are equal before comparing characters (O(1) checks)", "Strings are hashed instantly", "It always takes O(N)"], 1, "CPython checks `is` (identity) and `len()` first. If lengths differ, it instantly returns False. If identity matches, it instantly returns True.")
    add_q("Comparing Strings & Naming Variables", "What is the 'string interning' mechanism in Python?", ["Translating strings to other languages", "Caching specific strings (like short identifiers) so that identical strings point to the exact same object in memory", "Encrypting strings", "Compressing text files"], 1, "Interning saves memory and allows O(1) comparison for dictionary keys and identifiers by ensuring only one copy of a string exists.")
    add_q("Comparing Strings & Naming Variables", "How can you manually force a string to be interned?", ["str.intern()", "sys.intern()", "string.cache()", "You cannot"], 1, "The `sys.intern(string)` function enters the string into the table of interned strings.")
    add_q("Comparing Strings & Naming Variables", "What happens if you use a reserved keyword like `class` as an attribute name in an object (e.g., `setattr(obj, 'class', 'Math')`)?", ["SyntaxError", "It is stored successfully, but cannot be accessed via dot notation (`obj.class`)", "It crashes the interpreter", "It is automatically renamed"], 1, "You can store it dynamically, but `obj.class` will raise a SyntaxError. You must access it via `getattr(obj, 'class')`.")
    add_q("Comparing Strings & Naming Variables", "Which PEP defines the official style guide for naming variables, classes, and modules?", ["PEP 20", "PEP 8", "PEP 484", "PEP 257"], 1, "PEP 8 is the Style Guide for Python Code, defining snake_case for variables and CapWords for classes.")
    add_q("Comparing Strings & Naming Variables", "What is the semantic meaning of a single trailing underscore in a variable name (e.g., `class_`)?", ["It indicates a private variable", "It is used by convention to avoid conflicts with Python keywords", "It indicates an unused variable", "It causes name mangling"], 1, "When you need a variable name that is a keyword (like `class` or `def`), the convention is to append an underscore.")
    add_q("Comparing Strings & Naming Variables", "What is the result of `'ß'.casefold() == 'ss'`?", ["True", "False", "TypeError", "None"], 0, "`casefold()` converts the German sharp s ('ß') to 'ss', allowing accurate caseless matching that `lower()` misses.")
    add_q("Comparing Strings & Naming Variables", "In Python 3, are all strings Unicode by default?", ["Yes", "No, they are ASCII", "No, they are byte strings", "Only if prefixed with 'u'"], 0, "In Python 3, all strings (`str`) are sequences of Unicode characters.")
    add_q("Comparing Strings & Naming Variables", "What is a 'dunder' variable in Python?", ["A variable used for division", "A 'Double UNDERscore' variable (e.g., `__name__`) used for system-defined special names", "A deprecated variable", "A variable that cannot be deleted"], 1, "Dunder methods and variables have special meaning to the Python interpreter.")
    add_q("Comparing Strings & Naming Variables", "How does Python handle non-ASCII characters in variable names (e.g., `piπ = 3.14`)?", ["Raises a SyntaxError", "Perfectly valid in Python 3", "Converts them to ASCII", "Valid only in comments"], 1, "Python 3 natively supports UTF-8, allowing variables to be named using characters from almost any language/symbol set.")

    # 15. Lists
    add_q("Lists", "Under the hood, how is a Python `list` implemented in CPython?", ["As a Linked List", "As a Doubly Linked List", "As an array of pointers (a variable-length array)", "As a Binary Tree"], 2, "A Python list is a dynamic array of pointers to objects, which is why accessing by index is O(1) but inserting at the front is O(N).")
    add_q("Lists", "What happens to the memory allocation of a list when it exceeds its current capacity during an `append`?", ["It throws a MemoryError", "It allocates exactly one more slot", "It allocates a larger array (over-allocates) and copies the old pointers over", "It switches to a linked list"], 2, "Lists over-allocate memory to achieve an amortized O(1) append time.")
    add_q("Lists", "What is the output of `a = [[]] * 3; a[0].append(1); print(a)`?", ["[[1], [], []]", "[[1], [1], [1]]", "[[1]]", "Error"], 1, "The `*` operator creates multiple references to the exact same inner list. Appending to one modifies all of them.")
    add_q("Lists", "How do you properly create a 3x3 matrix initialized to 0 without referencing issues?", ["[[0]*3]*3", "[[0,0,0]]*3", "[[0 for _ in range(3)] for _ in range(3)]", "list(0, 3, 3)"], 2, "A nested list comprehension creates distinct inner lists, preventing the reference duplication issue of the `*` operator.")
    add_q("Lists", "What is the time complexity of `x in lst` for a Python list?", ["O(1)", "O(log N)", "O(N)", "O(N^2)"], 2, "The `in` operator performs a linear search through the list, resulting in O(N) time complexity.")
    add_q("Lists", "What is the output of `lst = [1, 2, 3]; lst[1:2] = [4, 5, 6]; print(lst)`?", ["[1, 4, 5, 6, 3]", "[1, [4, 5, 6], 3]", "Error", "[1, 4, 3]"], 0, "Slice assignment replaces the targeted slice (index 1) with the elements of the iterable, expanding the list if necessary.")
    add_q("Lists", "Is it possible to hash a Python list (e.g., use `hash([1,2])`)?", ["Yes", "No, it raises a TypeError because lists are mutable", "Only if it contains integers", "Yes, it returns a unique ID"], 1, "Mutable objects like lists cannot be hashed, preventing them from being dictionary keys or set elements.")
    add_q("Lists", "What is the result of `del lst[:]`?", ["Deletes the list object entirely", "Clears all elements from the list, leaving it empty", "Raises a SyntaxError", "Deletes only the first element"], 1, "It deletes the slice representing the entire list, mutating it to `[]` in place (equivalent to `lst.clear()`).")
    add_q("Lists", "What happens when you `pop()` from an empty list?", ["Returns None", "Raises an IndexError", "Returns 0", "Raises a KeyError"], 1, "Attempting to pop from an empty list raises an `IndexError: pop from empty list`.")
    add_q("Lists", "What is Timsort?", ["A module for time manipulation", "Python's standard sorting algorithm, a hybrid of Merge Sort and Insertion Sort", "A hashing algorithm for lists", "A built-in method for tree sorting"], 1, "Timsort (used by `list.sort()`) is highly optimized for real-world data, running in O(N log N) time and performing exceptionally well on partially sorted lists.")

    # 16. Working with Lists
    add_q("Working with Lists", "When should you use `collections.deque` instead of a Python `list`?", ["When you need to sort data quickly", "When you need fast O(1) appends and pops from BOTH ends of the sequence", "When you need to store mixed data types", "When memory is unlimited"], 1, "Lists take O(N) to `insert(0, val)` or `pop(0)`. A `deque` (doubly linked list) takes O(1) for operations on either end.")
    add_q("Working with Lists", "What is the difference between `list.sort()` and `sorted(list)` in terms of memory?", ["`list.sort()` uses more memory", "`list.sort()` operates in-place (O(1) extra space), while `sorted()` creates a new list (O(N) space)", "There is no difference", "`sorted()` modifies the original list"], 1, "In-place sorting is more memory efficient because it avoids allocating a new list object.")
    add_q("Working with Lists", "How do you deep copy a list containing nested mutable objects?", ["list.copy()", "list[:]", "copy.deepcopy(list)", "list(list)"], 2, "The `copy.deepcopy()` function recursively duplicates all nested mutable objects to completely decouple the copy from the original.")
    add_q("Working with Lists", "What happens if a list's `sort()` method is called on a list of mixed data types (e.g., `[1, 'a', 2]`) in Python 3?", ["It sorts them based on memory address", "It sorts numbers first, then strings", "It raises a TypeError", "It converts everything to strings and sorts"], 2, "Python 3 prevents ordering comparisons between incompatible types, raising a TypeError.")
    add_q("Working with Lists", "What does the `bisect` module do?", ["Splits a list in half", "Provides functions to maintain a list in sorted order using binary search (O(log N))", "Sorts a list in O(N)", "Deletes duplicates"], 1, "The `bisect` module helps insert items into a sorted list without having to re-sort the list each time.")
    add_q("Working with Lists", "What is the output of `lst = [1]; lst.append(lst); print(lst)`?", ["An infinite loop", "A MemoryError", "`[1, [...]]` (A self-referencing list)", "Error"], 2, "The list contains a reference to itself. Python's print function detects this cycle and safely prints `[...]` instead of looping infinitely.")
    add_q("Working with Lists", "How can you flatten a deeply nested list of unknown depth?", ["Using a list comprehension", "Using `itertools.chain`", "Writing a recursive generator/function", "Using `list.flatten()`"], 2, "Because the depth is arbitrary, a recursive function checking `isinstance(x, list)` is required.")
    add_q("Working with Lists", "What is the most efficient way to remove duplicates from a list while maintaining order?", ["`list(set(lst))`", "`[x for i, x in enumerate(lst) if x not in lst[:i]]`", "`list(dict.fromkeys(lst))`", "`lst.sort()`"], 2, "Since Python 3.7, dictionaries maintain insertion order. `dict.fromkeys(lst)` is O(N) and keeps the order perfectly.")
    add_q("Working with Lists", "What is the output of `x = [1, 2, 3]; y = x.reverse(); print(y)`?", ["[3, 2, 1]", "None", "[1, 2, 3]", "Error"], 1, "In-place methods like `reverse()` return `None` to prevent confusion with methods that return new objects.")
    add_q("Working with Lists", "If `x = [1, 2, 3]`, what does `x[1:1] = [9, 10]` result in?", ["Replaces element 1 with [9, 10]", "Raises an error", "`[1, 9, 10, 2, 3]` (inserts elements without deleting)", "`[1, 9, 10, 3]`"], 2, "A slice of length zero (1:1) acts as an insertion point, effectively inserting the elements at index 1 without replacing existing ones.")

    # 17. Lists and Strings
    add_q("Lists and Strings", "Why is `''.join(list_of_strings)` preferred over a `for` loop with `+=` string concatenation?", ["It is syntactically shorter", "Strings are immutable; `+=` creates a new string every iteration leading to O(N^2) complexity. `join` computes memory once (O(N)).", "It prevents SyntaxErrors", "It automatically converts integers to strings"], 1, "`join` calculates the total memory needed for the final string upfront, avoiding constant reallocation.")
    add_q("Lists and Strings", "What is the output of `'abc'.split('')`?", ["['a', 'b', 'c']", "Raises a ValueError: empty separator", "['abc']", "['', 'a', 'b', 'c', '']"], 1, "Python's `split()` method does not accept an empty string as a separator. To split by character, use `list('abc')`.")
    add_q("Lists and Strings", "How can you replace multiple different characters in a string efficiently?", ["Chaining multiple `.replace()` calls", "Using a regex or `str.translate(str.maketrans(...))`", "Converting to a list, using a loop, and joining", "It is impossible"], 1, "`str.translate` is written in C and is highly optimized for replacing or mapping multiple characters simultaneously.")
    add_q("Lists and Strings", "What is the output of `list(map(list, ['ab', 'cd']))`?", ["[['a', 'b'], ['c', 'd']]", "['a', 'b', 'c', 'd']", "['ab', 'cd']", "Error"], 0, "The `map` function applies `list()` to each string, converting 'ab' to ['a', 'b'] and 'cd' to ['c', 'd'].")
    add_q("Lists and Strings", "What does `bytes.fromhex('48656c6c6f').decode('utf-8')` do?", ["Throws an error", "Converts a hex string into binary, then decodes it into the string 'Hello'", "Returns '48656c6c6f'", "Returns an array of integers"], 1, "It takes a hexadecimal representation of bytes, constructs the bytes object, and decodes it via UTF-8 into text.")
    add_q("Lists and Strings", "If `s = 'hello'`, what does `s[::-1]` internally do in CPython?", ["Loops backwards through the string in Python", "Returns an iterator", "Allocates a new string and copies characters backwards in C, running in O(N)", "Modifies the string in place"], 2, "Because strings are immutable, slicing always allocates a new string, copying the data efficiently at the C level.")
    add_q("Lists and Strings", "How do you evaluate a list of strings containing numbers (e.g., `['1', '2']`) into a list of integers?", ["`int(['1', '2'])`", "`[int] * ['1', '2']`", "`[int(x) for x in ['1', '2']]` or `list(map(int, ['1', '2']))`", "`eval(['1', '2'])`"], 2, "List comprehensions or the `map` function are the standard, safe ways to apply a type conversion to all elements.")
    add_q("Lists and Strings", "What is the output of `'a'.join('123')`?", ["1a2a3", "a1a2a3", "123a", "Error"], 0, "The `join()` method iterates over the string '123' (which acts as a sequence of characters) and inserts 'a' between them.")
    add_q("Lists and Strings", "Is it faster to search for a substring in a string (`'a' in str`) or a list of characters (`'a' in lst`)?", ["List search is faster", "String search is highly optimized in C (Boyer-Moore algorithm) and is significantly faster", "They are identical", "Depends on the character"], 1, "String membership checking is highly optimized internally, making it much faster than traversing a list object by object.")
